import { step, glide } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BELL = "violet";
const INNER = "plum";
const TENTACLE = "mistyrose";

export function spawn() {
  return { phase: Math.random() * Math.PI * 2, arms: [0, 0, 0, 0, 0] };
}

export function update(jelly, world) {
  jelly.phase += 0.05;
  jelly.vy = Math.sin(jelly.phase) * 0.6;
  jelly.vx = Math.cos(jelly.phase * 0.3) * 0.4;
  glide(jelly, 1);
  step(jelly);
  bounce(jelly);
  jelly.arms.shift();
  jelly.arms.push(jelly.y);
}

export function draw(jelly, pen) {
  const pulse = 1 + Math.sin(jelly.phase) * 0.1;
  pen.fill(BELL);
  pen.ellipse(0, 0, 18 * pulse, 14 * pulse);
  pen.fill(INNER);
  pen.ellipse(0, -3, 10 * pulse, 7 * pulse);
  pen.stroke(TENTACLE, 2);
  for (let i = 0; i < jelly.arms.length; i += 1) {
    const wiggle = Math.sin(jelly.phase + i) * (i + 2);
    pen.line(i * 6 - 12, 10, i * 6 - 12 + wiggle, 26 + i * 5);
  }
}

