import { keepInside } from "../world/bounds.js";
import { step, glide, wander } from "../world/movement.js";

const BODY = "coral";
const BELLY = "gold";
const CROWN = "darkgreen";
const EYE = "black";

export const count = 2;

export function spawn(world) {
  return {
    x: world.width * 0.2 + Math.random() * world.width * 0.6,
    y: world.height * 0.2 + Math.random() * world.height * 0.5,
    vx: 0,
    vy: 0,
    bobOffset: Math.random() * Math.PI * 2,
  };
}

export function update(seahorse, world) {
  seahorse.bobOffset += 0.08;
  seahorse.vy += Math.sin(seahorse.bobOffset) * 0.04;
  wander(seahorse, 0.03);
  glide(seahorse, 0.95);
  step(seahorse);
  keepInside(seahorse);
}

export function draw(seahorse, pen, world) {
  const lean = Math.max(-0.4, Math.min(0.4, seahorse.vx * 0.1));
  pen.turn(lean);

  // Tail curl
  pen.fill(BODY);
  pen.poly([0, 24, -8, 38, 0, 44, 8, 38]);

  // Body
  pen.fill(BODY);
  pen.ellipse(0, 0, 12, 22);

  // Belly
  pen.fill(BELLY);
  pen.ellipse(0, 4, 7, 14);

  // Snout
  pen.fill(BODY);
  pen.ellipse(6, -14, 4, 7);

  // Crown
  pen.fill(CROWN);
  pen.poly([-3, -18, -6, -28, 0, -24, 4, -29, 3, -18]);

  // Eye
  pen.fill(EYE);
  pen.circle(4, -12, 2);
}

