import { FLOOR_Y } from "../world/bounds.js";

const BODY = "purple";
const SPINES = "black";
const SAND = "sand";

export const count = 4;

export function spawn() {
  return {
    y: FLOOR_Y + 3,
    wave: Math.random() * Math.PI * 2,
  };
}

export function update(urchin, world) {
  urchin.wave += 0.12;
}

export function draw(urchin, pen) {
  pen.fill(SAND);
  pen.ellipse(0, 8, 22, 8, 0);
  pen.fill(BODY);
  pen.circle(0, 0, 12);
  pen.stroke(SPINES, 2);
  const co = Math.cos(urchin.wave);
  for (let i = 0; i < 12; i += 1) {
    const angle = (i / 12) * Math.PI * 2;
    const inner = 10;
    const outer = 18 + (i % 2 === 0 ? 5 + co * 3 : 3 + Math.sin(urchin.wave + 1) * 2);
    pen.line(
      Math.cos(angle) * inner,
      Math.sin(angle) * inner,
      Math.cos(angle) * outer,
      Math.sin(angle) * outer
    );
  }
}

