import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { step, steer, glide, wander } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";
import { isNight } from "../world/time.js";

const BODY = "darkslategray";
const FIN = "slategray";
const LURE = "palegoldenrod";
const GLOW = "lemonchiffon";

export function spawn() {
  return { vx: 1, energy: ENERGY_MAX };
}

export function update(angler, world) {
  const food = isHungry(angler) ? nearestFood(angler, world) : null;
  if (food) steer(angler, food.x, food.y, 0.15);
  else wander(angler, 0.08);
  glide(angler, 0.97);
  step(angler);
  keepInside(angler);
}

export function draw(angler, pen, world) {
  if (angler.vx < 0) pen.flip();

  // Lure stalk and glowing lure, only visible at night.
  if (isNight(world)) {
    const glow = 0.4 + 0.3 * Math.sin(world.tick * 0.1);
    pen.fill(GLOW);
    pen.alpha(glow);
    pen.circle(28, -28, 5);
    pen.alpha(1);
    pen.line(20, -14, 28, -28);
  }

  pen.fill(FIN);
  pen.poly([-16, 0, -30, -12, -30, 12]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 22, 14);
  pen.fill("black");
  pen.circle(10, -3, 2.5);

  // Dorsal and pectoral fins.
  pen.fill(FIN);
  pen.poly([0, -14, -10, -24, 8, -18]);
  pen.poly([4, 8, -6, 16, 10, 14]);
}

