import { step, steer, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "#4aa3df";
const FIN = "#8ecae6";
const EYE = "black";

export const count = 8;

export function spawn() {
  return { vx: 0.8, vy: 0.1 };
}

export function update(fish, world) {
  // Find the average position and heading of the other bluefish.
  let avgX = 0;
  let avgY = 0;
  let headingX = 0;
  let headingY = 0;
  let nearby = 0;

  for (const other of world.creatures) {
    if (other.kind === "bluefish" && other !== fish) {
      const dx = other.x - fish.x;
      const dy = other.y - fish.y;
      const d = Math.hypot(dx, dy);
      if (d < 60) {
        avgX += other.x;
        avgY += other.y;
        headingX += other.vx;
        headingY += other.vy;
        nearby++;
      }
      // Keep a little apart so they do not stack.
      if (d < 14 && d > 0.001) {
        fish.vx -= (dx / d) * 0.18;
        fish.vy -= (dy / d) * 0.18;
      }
    }
  }

  // Drift with the school.
  if (nearby > 0) {
    avgX /= nearby;
    avgY /= nearby;
    headingX /= nearby;
    headingY /= nearby;

    steer(fish, avgX, avgY, 0.06);
    if (Math.hypot(headingX, headingY) > 0.001) {
      fish.vx += (headingX / nearby) * 0.045;
      fish.vy += (headingY / nearby) * 0.045;
    }
  }

  // Swim slowly forward.
  if (Math.abs(fish.vx) < 0.3 && Math.abs(fish.vy) < 0.3) {
    fish.vx += fish.facing === -1 ? -0.3 : 0.3;
  }

  glide(fish, 0.96);
  step(fish);
  wrap(fish);

  // Remember which way we were heading for drawing.
  fish.facing = fish.vx < 0 ? -1 : 1;
}

export function draw(fish, pen) {
  if (fish.facing === -1) pen.flip();

  pen.fill(FIN);
  pen.poly([-8, 0, -15, -5, -15, 5]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 10, 5);
  pen.fill(FIN);
  pen.ellipse(0, -3, 4, 2);
  pen.fill(EYE);
  pen.circle(4, -1, 1);
}

