import { ENERGY_MAX } from "../world/energy.js";
import { step, glide, distance } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BODY = "yellow";
const BELLY = "white";
const SPINES = "black";
const EYE = "white";

const PUFF_DISTANCE = 90;
const PUFF_SPEED = 0.08;
const SWIM_SPEED = 0.22;

export function spawn() {
  return {
    vx: 0.8,
    vy: 0.2,
    energy: ENERGY_MAX,
    puff: 0,
  };
}

function nearestCreature(puffer, world) {
  let nearest = null;
  let nearestDistance = Infinity;
  for (const other of world.creatures) {
    if (other === puffer) continue;
    const far = distance(puffer, other);
    if (far < nearestDistance) {
      nearest = other;
      nearestDistance = far;
    }
  }
  return nearest;
}

function pickTarget(puffer) {
  const x = 50 + Math.random() * 700;
  const y = 60 + Math.random() * 360;
  puffer.tx = x;
  puffer.ty = y;
}

export function update(puffer, world) {
  const other = nearestCreature(puffer, world);
  const close = other && distance(puffer, other) < PUFF_DISTANCE;

  if (close) {
    puffer.puff = Math.min(1, puffer.puff + PUFF_SPEED);
    puffer.vx *= 0.9;
    puffer.vy *= 0.9;
  } else {
    puffer.puff = Math.max(0, puffer.puff - PUFF_SPEED);
    if (!puffer.tx || Math.hypot(puffer.x - puffer.tx, puffer.y - puffer.ty) < 20) {
      pickTarget(puffer);
    }
    const dx = puffer.tx - puffer.x;
    const dy = puffer.ty - puffer.y;
    const far = Math.hypot(dx, dy);
    if (far > 0.001) {
      puffer.vx += (dx / far) * SWIM_SPEED;
      puffer.vy += (dy / far) * SWIM_SPEED;
    }
  }

  glide(puffer, 0.96);
  step(puffer);
  bounce(puffer);
}

export function draw(puffer, pen) {
  if (puffer.vx < 0) pen.flip();

  const puff = puffer.puff || 0;
  const bodyR = 12 + puff * 10;

  pen.fill(BODY);
  pen.circle(0, 0, bodyR);
  pen.fill(BELLY);
  pen.circle(-2, 2, bodyR * 0.55);

  pen.stroke(SPINES);
  const spines = 8;
  for (let i = 0; i < spines; i += 1) {
    const angle = (i / spines) * 2 * Math.PI;
    const r = bodyR - 1;
    const sx = Math.cos(angle) * r;
    const sy = Math.sin(angle) * r;
    const tx = Math.cos(angle) * (r + 4 + puff * 6);
    const ty = Math.sin(angle) * (r + 4 + puff * 6);
    pen.line(sx, sy, tx, ty);
  }

  pen.fill(SPINES);
  pen.circle(bodyR - 3, -4, 3);
  pen.fill(EYE);
  pen.circle(bodyR - 3, -4, 1.5);
}

