import { ENERGY_MAX } from "../world/energy.js";
import { FLOOR_Y, bounce } from "../world/bounds.js";
import { step, wander, glide } from "../world/movement.js";

const SHELL = "crimson";
const BODY = "coral";
const EYE = "black";

const HIDE_BELOW = ENERGY_MAX * 0.3;

export function spawn() {
  return { y: FLOOR_Y - 6, vx: 0.6, energy: ENERGY_MAX };
}

export function update(crab, world) {
  if (!crab.hiding && crab.energy < HIDE_BELOW) {
    crab.hiding = true;
  }
  if (crab.hiding && crab.energy >= HIDE_BELOW + ENERGY_MAX * 0.1) {
    crab.hiding = false;
  }

  if (!crab.hiding) {
    wander(crab, 0.15);
    glide(crab, 0.92);
    step(crab);
    bounce(crab);
  }
}

export function draw(crab, pen) {
  if (crab.vx < 0) pen.flip();

  pen.fill(SHELL);
  pen.ellipse(0, 0, 18, 13);

  if (!crab.hiding) {
    pen.fill(BODY);
    pen.rect(-10, -5, 20, 10, 4);
    pen.fill(EYE);
    pen.circle(7, -5, 2);
    pen.line(-6, 2, -14, 8);
    pen.line(6, 2, 14, 8);
  } else {
    pen.fill(BODY);
    pen.rect(-8, -3, 16, 6, 3);
  }
}

